    46	Guint Linearization::getLength()
    47	{
    48	  if (!linDict.isDict()) return 0;
    49	
    50	  int length;
    51	  if (linDict.getDict()->lookupInt("L", nullptr, &length) &&
    52	      length > 0) {
    53	    return length;
    54	  } else {
    55	    error(errSyntaxWarning, -1, "Length in linearization table is invalid");
